import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long x = Long.parseLong(br.readLine().trim());
        long r = ((-x) % 360 + 360) % 360;
        int best = 0;
        long bestDev = Long.MAX_VALUE;
        for (int k = 0; k < 4; k++) {
            long t = (r + 90L * k) % 360;
            long dev = Math.min(t, 360 - t);
            if (dev < bestDev) {
                bestDev = dev;
                best = k;
            }
        }
        System.out.println(best);
    }
}
